// OpenRouter: generate an image, then hand its path to the next step.
// Runs in Layla's QuickJS `eval` runtime (fetch + the Layla SDK as `layla`).
// Returns the image path relative to the character workspace, which display-image resolves.

const API_KEY = 'PUT YOUR API KEY HERE';
// The prompt is pasted in by Layla before this code runs. A backtick or `${` in it would end the literal.
const PROMPT = String.raw`{{match$1}}`.trim();

// Copy the model ID from the model's page on openrouter.ai.
const MODEL_ID = 'black-forest-labs/flux-3-image-klein';
const RESOLUTION = '1K'; // '' to use the model's default
const ASPECT_RATIO = ''; // e.g. '16:9' or '9:16'; '' to use the model's default
const API_URL = 'https://openrouter.ai/api/v1/images';
const TIMEOUT_MS = 90000;

async function generateImage(prompt) {
  if (!prompt) throw new Error('The stable diffusion prompt was empty.');
  if (!API_KEY || API_KEY === 'PUT YOUR API KEY HERE') throw new Error('Set API_KEY in this agent first.');

  // Not every model accepts every setting, so only send the ones that are set.
  const payload = { model: MODEL_ID, prompt };
  if (RESOLUTION) payload.resolution = RESOLUTION;
  if (ASPECT_RATIO) payload.aspect_ratio = ASPECT_RATIO;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  let response;
  let body;
  try {
    response = await fetch(API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${API_KEY}` },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    body = await response.text();
  } catch (error) {
    if (controller.signal.aborted) throw new Error(`Image generation timed out after ${TIMEOUT_MS / 1000} s.`);
    throw new Error(`Image generation request failed: ${error.message}`);
  } finally {
    clearTimeout(timer);
  }

  if (!response.ok) {
    throw new Error(`HTTP error ${response.status} ${response.statusText}. Response body: ${body.slice(0, 500)}`);
  }

  let data;
  try {
    data = JSON.parse(body);
  } catch (error) {
    throw new Error(`The response was not JSON: ${body.slice(0, 200)}`);
  }

  // The Image API answers with { data: [{ b64_json, media_type }], usage }.
  for (const image of data.data || []) {
    if (!image || !image.b64_json) continue;

    const mediaType = String(image.media_type || 'image/png');
    const extension = mediaType.split('/').pop().split('+')[0].replace(/[^a-z0-9]/gi, '') || 'png';
    const id = Math.random().toString(16).slice(2, 10).padEnd(8, '0');
    const path = `generated-images/output_image_${id}.${extension}`;

    // The API already returns base64, so it goes to the workspace as is.
    await layla.utils.saveFile(path, image.b64_json);
    return path;
  }

  const detail = data.error && data.error.message ? data.error.message : `Response keys: ${Object.keys(data).join(', ')}`;
  throw new Error(`No image was found in the response. ${detail}`);
}

generateImage(PROMPT);
